import {example,compare} from './engine.mjs';
let lang='tr',current=[],x={...example};
const en={prototype:'First release',eyebrow:'CALCULATE BEFORE YOU SELL',headline:'Grow your campaign.<br>Protect your profit.',lead:'Discounts, bundles or free shipping. Compare four options with the same costs and make an informed decision.',note:'More revenue does not<br>always mean more profit.',inputs:'01 / Product & costs',example:'Load example',sample:'Illustrative starting values. All amounts in TRY.',settings:'VAT & commission settings',assumptions:'Product sales and customer delivery charges include product VAT. Expense VAT is assumed recoverable. Profit is before income/corporate tax.',calculate:'Compare scenarios ↗',privacy:'Calculated in your browser. Your inputs are neither sent to a server nor saved.',results:'02 / Campaign comparison',breakdown:'Where does the money go?',netnote:'Revenue and costs below exclude VAT. Break-even is the order’s product total after discount; customer delivery is separate.',method:'Method & limitations',formula:'Profit = revenue excluding VAT − product cost − commission − shipping − other costs. Margin = profit / revenue excluding VAT. A bundle contains two of the same product; shipping and other costs apply per order.',limits:'Scenario calculation, not a sales forecast. Include returns, advertising and platform fees in other costs as appropriate. Shipping tiers and variable commission schedules are not applied automatically.',footer:'One product, one clear decision. Now see your whole store.',cta:'Explore Makskar ↗'};
const tr={};document.querySelectorAll('[data-t]').forEach(e=>tr[e.dataset.t]=e.innerHTML);
const names={tr:['Normal satış','İndirimli satış','İkili paket','Ücretsiz kargo'],en:['Standard sale','Discounted sale','Two-item bundle','Free shipping']};
const labels={price:['Satış fiyatı · KDV dahil','Sale price · incl. VAT'],cost:['Alış maliyeti · adet başına','Purchase cost · per item'],shipping:['Kargo gideri · sipariş','Shipping cost · per order'],shippingIncome:['Müşteriden alınan kargo','Customer delivery charge'],other:['Diğer giderler · sipariş','Other costs · per order'],rate:['Komisyon oranı (%)','Commission rate (%)'],discount:['Tekli satış indirimi (%)','Single-item discount (%)'],bundleDiscount:['Paket indirimi (%)','Bundle discount (%)'],bundleShipping:['İkili paketin kargo gideri','Bundle shipping cost'],vat:['Ürün KDV oranı (%)','Product VAT (%)'],costVat:['Alış KDV oranı (%)','Purchase VAT (%)'],shippingVat:['Kargo KDV oranı (%)','Shipping VAT (%)'],otherVat:['Diğer gider KDV oranı (%)','Other cost VAT (%)'],commissionVat:['Komisyon KDV oranı (%)','Commission VAT (%)']};
const t=(a,b)=>lang==='tr'?a:b, money=n=>n===null?'—':new Intl.NumberFormat(lang==='tr'?'tr-TR':'en-GB',{style:'currency',currency:'TRY',maximumFractionDigits:2}).format(n);
function field(k){return `<div class="field"><label for="${k}">${labels[k][lang==='tr'?0:1]}</label><input id="${k}" name="${k}" type="number" inputmode="decimal" step="0.01" min="${k==='price'?'0.01':'0'}" ${['vat','costVat','shippingVat','otherVat','commissionVat','rate','discount','bundleDiscount'].includes(k)?'max="100"':''} value="${x[k]}" required></div>`}
function choice(k,label,a,b){return `<div class="field"><label for="${k}">${label}</label><select id="${k}" name="${k}"><option value="true" ${x[k]?'selected':''}>${a}</option><option value="false" ${!x[k]?'selected':''}>${b}</option></select></div>`}
function setup(){document.documentElement.lang=lang;document.querySelectorAll('[data-t]').forEach(e=>e.innerHTML=(lang==='tr'?tr:en)[e.dataset.t]);document.querySelector('#language').textContent=lang==='tr'?'EN':'TR';document.querySelector('#fields').innerHTML=['price','cost','shipping','shippingIncome','other','rate'].map(field).join('')+`<div class="subhead">${t('Kampanya seçenekleri','Campaign options')}</div>`+['discount','bundleDiscount','bundleShipping'].map(field).join('');document.querySelector('#settings').innerHTML=choice('included',t('Alış, kargo ve diğer gider girişleri','Purchase, shipping & other cost inputs'),t('KDV dahil','VAT included'),t('KDV hariç','VAT excluded'))+['vat','costVat','shippingVat','otherVat','commissionVat'].map(field).join('')+choice('commissionIncluded',t('Girilen komisyon oranı','Entered commission rate'),t('Komisyon KDV’si dahil','Includes commission VAT'),t('Komisyon KDV’si hariç','Excludes commission VAT'))+choice('baseGross',t('Komisyon matrahı','Commission basis'),t('KDV dahil satış','Sales including VAT'),t('KDV hariç satış','Sales excluding VAT'))+choice('commissionShipping',t('Müşteri kargosu komisyona dahil mi?','Commission on customer delivery?'),t('Evet','Yes'),t('Hayır','No'));document.querySelector('#detail').innerHTML=names[lang].map((n,i)=>`<option value="${i}">${n}</option>`).join('');render()}
function read(){const data=new FormData(document.querySelector('#inputs'));for(const k in example)x[k]=typeof example[k]==='boolean'?data.get(k)==='true':Number(data.get(k));}
function render(){try{current=compare(x);document.querySelector('#error').textContent='';}catch{document.querySelector('#error').textContent=t('Lütfen geçerli, sıfır veya pozitif tutarlar girin. Satış fiyatı sıfırdan büyük, oranlar 0–100 arasında olmalı.','Enter valid non-negative amounts. Sale price must be positive and percentages must be between 0 and 100.');return}
 const best=Math.max(...current.map(s=>s.unit));const bestI=current.findIndex(s=>s.unit===best);const extra=current[1].profit>0&&current[0].profit>0?Math.max(0,(current[0].profit/current[1].profit-1)*100):null;
 document.querySelector('#state').textContent=t('● Hesaplandı','● Calculated');
 document.querySelector('#insight').innerHTML=`<strong>${best>0?t('Ürün başına en yüksek kâr: ','Highest profit per item: ')+names[lang][bestI]:t('Bu maliyetlerle kârlı bir seçenek yok.','No profitable option with these costs.')}</strong>${extra===null?t('Zarardaki bir satışın adedini artırmak zararı büyütür.','Increasing the volume of a loss-making sale increases the loss.'):t('İndirimli satışta aynı toplam kâr için yaklaşık %','To match standard-sale total profit, discounted sales need about ')+extra.toFixed(1)+t(' daha fazla sipariş gerekir. Bu bir satış tahmini değildir.','% more orders. This is not a sales forecast.')}`;
 document.querySelector('#cards').innerHTML=current.map((s,i)=>{const row=(a,b)=>`<div class="metric"><span>${a}</span><b>${b}</b></div>`;return `<article class="scenario ${s.unit===best&&best>0?'best':''}">${s.unit===best&&best>0?`<span class="badge">${t('EN YÜKSEK BİRİM KÂR','BEST PER ITEM')}</span>`:''}<h3>${names[lang][i]}</h3><div class="caption">${s.q} ${t('adet · ürün toplamı','item(s) · product total')} ${money(s.sales)}</div><div class="profit ${s.profit<0?'loss':''}">${money(s.profit)}</div><div class="caption">${t('Sipariş başına kâr · vergi öncesi','Profit per order · before income tax')}</div><div class="metrics">${row(t('Ürün başına kâr','Profit per item'),money(s.unit))}${row(t('Kâr marjı','Profit margin'),s.margin.toFixed(2)+'%')}${row(t('Başabaş ürün toplamı','Break-even product total'),s.breakEven===null?t('Mümkün değil','Not attainable'):money(s.breakEven))}${row(t('Normal satışa göre / adet','Vs standard / item'),money(s.unit-current[0].unit))}</div></article>`}).join('');bars();}
function bars(){const s=current[Number(document.querySelector('#detail').value)||0];if(!s)return;const items=[[t('Net gelir','Net revenue'),s.revenue],[t('Ürün maliyeti','Product cost'),s.goods],[t('Komisyon','Commission'),s.commission],[t('Kargo','Shipping'),s.shipping],[t('Diğer gider','Other costs'),s.other],[t('Kâr / zarar','Profit / loss'),s.profit]];document.querySelector('#bars').innerHTML=items.map(([label,v])=>`<div class="barrow"><span>${label}</span><div class="track"><div class="fill" style="width:${Math.min(100,Math.abs(v)/Math.max(1,s.revenue)*100)}%"></div></div><b class="${v<0?'loss':''}">${money(v)}</b></div>`).join('')}
document.querySelector('#inputs').addEventListener('submit',e=>{e.preventDefault();read();render()});document.querySelector('#inputs').addEventListener('input',()=>document.querySelector('#state').textContent=t('Değişiklikler bekliyor','Changes pending'));document.querySelector('#language').onclick=()=>{if(document.querySelector('#inputs').checkValidity())read();lang=lang==='tr'?'en':'tr';setup()};document.querySelector('#example').onclick=()=>{x={...example};setup()};document.querySelector('#detail').onchange=bars;setup();
